A17.Functions.copyTextToClipboard = function (textToCopy, successMsg) {

  var Clipboard = (function (window, document, navigator) {
    var textArea,
      copy;

    function isIOS() {
      return navigator.userAgent.match(/ipad|ipod|iphone/i);
    }

    function createTextArea(textToCopy) {
      textArea = document.createElement('textArea');
      textArea.value = textToCopy;

      // http://stackoverflow.com/questions/400212/how-do-i-copy-to-the-clipboard-in-javascript#answer-30810322
      //
      // *** This styling is an extra step which is likely not required. ***
      //
      // Why is it here? To ensure:
      // 1. the element is able to have focus and selection.
      // 2. if element was to flash render it has minimal visual impact.
      // 3. less flakyness with selection and copying which **might** occur if
      //    the textarea element is not visible.
      //
      // The likelihood is the element won't even render, not even a flash,
      // so some of these are just precautions. However in IE the element
      // is visible whilst the popup box asking the user for permission for
      // the web page to copy to the clipboard.
      //

      // Place in top-left corner of screen regardless of scroll position.
      textArea.style.position = 'fixed';
      textArea.style.top = 0;
      textArea.style.left = 0;

      // Ensure it has a small width and height. Setting to 1px / 1em
      // doesn't work as this gives a negative w/h on some browsers.
      textArea.style.width = '2em';
      textArea.style.height = '2em';

      // We don't need padding, reducing the size if it does flash render.
      textArea.style.padding = 0;

      // Clean up any borders.
      textArea.style.border = 'none';
      textArea.style.outline = 'none';
      textArea.style.boxShadow = 'none';

      // Avoid flash of white box if rendered for any reason.
      textArea.style.background = 'transparent';
      textArea.style.opacity = '0';

      // Set to readonly to prevent mobile devices opening a keyboard when
      // also to move page on iOS while iOS will scroll page to element when selected and zoom, while it is too small
      // text is .select()'ed.
      textArea.setAttribute('readonly', true);

      document.body.appendChild(textArea);
    }

    function selectText() {
      var range,
        selection;

      if (isIOS()) {
        textArea.contentEditable = true;
        range = document.createRange();
        range.selectNodeContents(textArea);
        selection = window.getSelection();
        selection.removeAllRanges();
        selection.addRange(range);
        textArea.setSelectionRange(0, 999999);
      } else {
        textArea.select();
      }
    }

    function copyToClipboard() {
      var success = document.execCommand('copy');
      document.body.removeChild(textArea);
      return success;
    }

    copy = function (text) {
      createTextArea(text);
      selectText();
      return copyToClipboard();
    };

    return {
      copy: copy
    };
  })(window, document, navigator);

  try {
    var successful = Clipboard.copy(textToCopy);
    if (successful) {
      if (window.alert) {
        window.alert(successMsg);
      }
    } else {
      //console.log('Oops, unable to copy');
    }
  } catch (err) {
    //console.log('Oops, unable to copy');
  }

};
